import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/extended_entities.dart';
class ActivityScreen extends ConsumerStatefulWidget{const ActivityScreen({super.key});@override ConsumerState<ActivityScreen> createState()=>_ActivityScreenState();}
class _ActivityScreenState extends ConsumerState<ActivityScreen>{final minutes=TextEditingController(),distance=TextEditingController(),note=TextEditingController();String type='Walk';@override void dispose(){minutes.dispose();distance.dispose();note.dispose();super.dispose();}
Future<void> add()async{final controller=ref.read(appControllerProvider);final p=controller.selectedPet;if(p==null)return;final e=ActivityEntry(id:DateTime.now().microsecondsSinceEpoch.toString(),petId:p.id,type:type,startedAt:DateTime.now(),durationMinutes:int.tryParse(minutes.text),distance:double.tryParse(distance.text),distanceUnit:controller.distanceUnit,note:note.text.trim());await ref.read(appControllerProvider).save('activity_entries',e.toMap());minutes.clear();distance.clear();note.clear();}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final entries=pet==null?<ActivityEntry>[]:c.items('activity_entries').map(ActivityEntry.fromMap).where((e)=>e.petId==pet.id).toList()..sort((a,b)=>b.startedAt.compareTo(a.startedAt));final week=entries.where((e)=>DateTime.now().difference(e.startedAt).inDays>=0&&DateTime.now().difference(e.startedAt).inDays<7).fold<int>(0,(n,e)=>n+(e.durationMinutes??0));return Scaffold(appBar:AppBar(title:const Text('Activity journal')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(title:const Text('Recorded activity · last 7 days'),subtitle:Text('$week minutes logged'),leading:const Icon(Icons.directions_walk))),const SizedBox(height:12),DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Activity'),items:['Walk','Play','Training','Enrichment','Other'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v!)),const SizedBox(height:10),Row(children:[Expanded(child:TextField(controller:minutes,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Duration (minutes)'))),const SizedBox(width:8),Expanded(child:TextField(controller:distance,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Distance (${c.distanceUnit})')))]),const SizedBox(height:10),TextField(controller:note,decoration:const InputDecoration(labelText:'Notes')),const SizedBox(height:12),FilledButton(onPressed:add,child:const Text('Save activity')),const SizedBox(height:18),const Text('History',style:TextStyle(fontSize:19,fontWeight:FontWeight.w800)),...entries.map((e)=>Card(child:ListTile(title:Text(e.type),subtitle:Text('${DateFormat.yMMMd().add_jm().format(e.startedAt)} · ${e.durationMinutes??'—'} min · ${e.distance??'—'} ${e.distanceUnit}')))),const Text('Summaries describe only what you recorded; they are not fitness scores or recommendations.') ]));}}
